def solve_a(n):
    if n == 1 or n == 2:
        return 1

    # Memoization dictionary
    memo = {}

    def get_a(k):
        if k in memo:
            return memo[k]
        if k == 1 or k == 2:
            return 1

        # Recurrence: a_k = a_{a_{k-1}} + a_{k - a_{k-1}}
        a_km1 = get_a(k - 1)

        # Check indices for safety (should be positive since a_k are positive)
        index1 = a_km1
        index2 = k - a_km1

        result = get_a(index1) + get_a(index2)
        memo[k] = result
        return result

    return get_a(n)

# Calculate up to 32
N_max = 32
results = {}
for i in range(1, N_max + 1):
    results[i] = solve_a(i)

print("--- Sequence ---")
for i in range(1, N_max + 1):
    print(f"a_{i} = {results[i]}")

print("\n--- Powers of 2 Check ---")
for k in range(1, 6):
    p = 2**k
    print(f"a_{p} = {results[p]}")
